<script module lang="ts">
    export const layout = { breadcrumbs: [{ title: 'Deposit', href: '/owner/deposits' }, { title: 'Detail akun', href: '#' }] };
</script>

<script lang="ts">
    import { Form, Link } from '@inertiajs/svelte';
    import AppHead from '@/components/AppHead.svelte';
    import InputError from '@/components/InputError.svelte';
    import { Button } from '@/components/ui/button';
    import { Input } from '@/components/ui/input';
    type Deposit = { id: number; required_amount_rupiah: number; received_rupiah: number; balance_rupiah: number; resident: { full_name: string; whatsapp_number: string } | null; property: { name: string } | null; room: { code: string } | null; booking_id: number | null; tenancy_id: number | null; settlement_status: string | null; booking_status: string | null; tenancy_status: string | null; settlement_id: number | null; can_reconcile_external_overpayment: boolean; invoices: { id: number; invoice_number: string; due_date: string; balance_rupiah: number; status: string }[]; movements: { id: number; kind: string; amount_rupiah: number; reason: string; created_at: string; cash_transaction_id: number | null; invoice_number: string | null }[]; temporary_liabilities: { id: number; initial_amount_rupiah: number; balance_rupiah: number; idempotency_key: string }[] };
    let { deposit, idempotency_key }: { deposit: Deposit; idempotency_key: string } = $props();
    const money = (value: number) => new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 }).format(value);
    const canSettle = $derived(deposit.balance_rupiah > 0 && !deposit.settlement_id && (['cancelled', 'no_show'].includes(deposit.booking_status ?? '') || ['completed', 'terminated'].includes(deposit.tenancy_status ?? '')));
    const outstandingRequired = $derived(Math.max(0, deposit.required_amount_rupiah - deposit.received_rupiah));
</script>

<AppHead title="Deposit jaminan" />
