    <section class="grid gap-4 sm:grid-cols-3"><article class="rounded-xl border bg-card p-5"><p class="text-sm text-muted-foreground">Kewajiban yang disepakati</p><p class="mt-2 text-xl font-semibold">{money(deposit.required_amount_rupiah)}</p></article><article class="rounded-xl border bg-card p-5"><p class="text-sm text-muted-foreground">Deposit diterima</p><p class="mt-2 text-xl font-semibold">{money(deposit.received_rupiah)}</p></article><article class="rounded-xl border bg-card p-5"><p class="text-sm text-muted-foreground">Saldo liability saat ini</p><p class="mt-2 text-xl font-semibold">{money(deposit.balance_rupiah)}</p><p class="mt-1 text-xs text-muted-foreground">Status settlement: {deposit.settlement_status ?? 'Belum dibuka'}</p></article></section>
