    {#if deposit.settlement_id}<section class="flex flex-wrap items-center justify-between gap-4 rounded-xl border bg-card p-5"><div><h2 class="font-semibold">Settlement deposit</h2><p class="mt-1 text-sm text-muted-foreground">Status: {deposit.settlement_status}</p></div><Link href={`/owner/deposit-settlements/${deposit.settlement_id}`} class="inline-flex rounded-md border px-4 py-2 text-sm">Lihat settlement</Link></section>{/if}
