iv class="space-y-2"><label for="external_reference" class="text-sm font-medium">Referensi transfer</label><Input id="external_reference" name="external_reference" maxlength={160} required /><InputError message={errors.external_reference} /></div><div class="space-y-2"><label for="reason" class="text-sm font-medium">Alasan rekonsiliasi</label><Input id="reason" name="reason" minlength={3} maxlength={1000} required /><InputError message={errors.reason} /></div><div class="space-y-2 sm:col-span-2"><label for="evidence" class="text-sm font-medium">Bukti penerimaan</label><input id="evidence" name="evidence" type="file" accept="image/jpeg,image/png,image/webp,application/pdf" required class="block w-full rounded-md border bg-background p-2 text-sm" /><InputError message={errors.evidence} /></div><div class="sm:col-span-2 flex justify-end"><Button type="submit" disabled={processing}>{processing ? 'Mencatat…' : 'Catat dana eksternal'}</Button></div>{/snippet}</Form></section>{/if}
