class="text-sm font-medium">Referensi transfer</label><Input id={`temporary_reference_${liability.id}`} name="external_reference" maxlength={160} /></div><div class="space-y-2 sm:col-span-2"><label for={`temporary_description_${liability.id}`} class="text-sm font-medium">Keterangan</label><Input id={`temporary_description_${liability.id}`} name="description" minlength={3} maxlength={1000} required /><InputError message={errors.description} /></div><div class="sm:col-span-2 flex justify-end"><Button variant="outline" type="submit" disabled={processing}>{processing ? 'Mencatat…' : 'Catat refund aktual'}</Button></div>{/snippet}</Form>{/each}</div></section>{/if}
    <section class="grid gap-4 lg:grid-cols-2"><article class="rounded-xl border bg-card p-5"><h2 class="font-semibold">Tagihan penyewa</h2>{#if deposit.invoices.length === 0}<p class="mt-3 text-sm text-muted-foreground">Tidak ada tagihan tenancy.</p>{:else}<div class="mt-3 divide-y">{#each deposit.invoices as invoice (invoice.id)}<Link href={`/owner/invoices/${invoice.id}`} class="flex justify-between gap-3 py-3 text-sm"><span>{invoice.invoice_number} · {invoice.due_date} · {invoice.status}</span><span>{money(invoice.balance_rupiah)}</span></Link>{/each}</div>{/if}</article><article class="rounded-xl border bg-card p-5"><h2 class="font-semibold">Riwayat liability deposit</h2>{#if deposit.movements.length === 0}<p class="mt-3 text-sm text-muted-foreground">Belum ada pergerakan dana deposit.</p>{:else}<div class="mt-3 divide-y">{#each deposit.movements as movement (movement.id)}<div class="flex justify-between gap-3 py-3 text-sm"><div><p class="font-medium">{movement.kind}{movement.invoice_number ? ` · ${movement.invoice_number}` : ''}</p><p class="text-xs text-muted-foreground">{movement.reason}</p></div><p>{movement.kind === 'receipt' ? '+' : '−'}{money(movement.amount_rupiah)}</p></div>{/each}</div>{/if}</article></section>
</main>
